const payload = $input.first().json;
const transaction = payload.transaction || {};
const invoicing_config = payload.configuration?.invoicing || {};
const mode = invoicing_config.mode || 'not_applicable';
const idempotency_key = `inv_${transaction.id}_${transaction.created_at}`;
const customer = payload.customer || {};
const items = payload.items || [];
const commercial = payload.commercial_context || {};

let result_success = true;
let result_outcome = 'action_completed';
let new_status = 'invoiced';
let next_action = null;
let invoice_data = null;
let error = null;

function validateInvoicingConfiguration() {
  const missingFields = [];

  if (mode === 'not_applicable') {
    return { valid: true, missing: [] };
  }

  if (mode === 'manual' || mode === 'external_provider') {
    if (!customer.email) missingFields.push('customer.email');
    if (!customer.document_type) missingFields.push('customer.document_type');
    if (!customer.document_number) missingFields.push('customer.document_number');
    if (!customer.name) missingFields.push('customer.name');
  }

  if (mode === 'external_provider') {
    if (!invoicing_config.provider) missingFields.push('provider');
    if (!invoicing_config.api_key) missingFields.push('api_key');
  }

  return {
    valid: missingFields.length === 0,
    missing: missingFields
  };
}

function buildInvoicePayload() {
  return {
    invoice_id: null,
    idempotency_key: idempotency_key,
    status: 'pending',
    mode: mode,
    customer: {
      name: customer.name || null,
      email: customer.email || null,
      document_type: customer.document_type || null,
      document_number: customer.document_number || null,
      phone: customer.phone || null,
      city: customer.city || null,
      address: customer.address || null
    },
    items: items.map(item => ({
      sku: item.sku,
      name: item.name,
      quantity: item.quantity,
      unit_price: item.unit_price,
      subtotal: item.quantity * item.unit_price
    })),
    totals: {
      currency: commercial.currency || 'COP',
      subtotal: commercial.subtotal || 0,
      discount: commercial.discount || 0,
      shipping: commercial.shipping_cost || 0,
      tax: commercial.tax || 0,
      total: commercial.total || 0
    },
    issued_at: null,
    issued_by: mode === 'external_provider' ? invoicing_config.provider : 'system',
    reference_transaction_id: transaction.id
  };
}

if (mode === 'not_applicable') {
  invoice_data = {
    mode: 'not_applicable',
    status: 'skipped',
    note: 'Invoicing not applicable for this business configuration'
  };
  new_status = transaction.status || 'payment_confirmed';
  next_action = 'resolve_fulfillment_route';
} else {
  const validation = validateInvoicingConfiguration();

  if (!validation.valid) {
    result_success = false;
    result_outcome = 'missing_data';
    new_status = 'invoicing_failed';
    next_action = 'handle_error';
    error = {
      code: 'INVOICING_CONFIGURATION_INCOMPLETE',
      category: 'configuration',
      message: 'Required invoicing configuration fields are missing.',
      retryable: false,
      details: { missing_fields: validation.missing }
    };
  } else {
    invoice_data = buildInvoicePayload();

    if (mode === 'manual') {
      new_status = 'awaiting_invoice_issuance';
      next_action = 'wait_invoice_event';
      result_outcome = 'action_pending';
    } else if (mode === 'external_provider') {
      new_status = 'requesting_external_invoice';
      next_action = 'request_external_invoice';
      result_outcome = 'action_pending';
    }
  }
}

return [{
  json: {
    ...payload,
    invoicing_execution: {
      mode: mode,
      configuration_valid: !error,
      processed_at: new Date().toISOString()
    }
  }
}, {
  json: {
    result: {
      success: result_success,
      outcome: result_outcome
    },
    transaction: {
      transaction_id: transaction.id,
      previous_status: transaction.status,
      current_status: new_status,
      sub_status: null,
      next_action: next_action
    },
    route: {
      selected_flow: 'DALIA_M5_Commerce_Orchestrator',
      effective_action: 'issue_invoice',
      reason: mode === 'not_applicable' ? 'invoicing_not_required' : 'invoicing_initiated'
    },
    response: {
      message_required: false,
      message_type: null,
      reply_text: null,
      requested_fields: []
    },
    data: {
      invoicing: invoice_data || {}
    },
    error: error,
    trace: {
      trace_id: payload.trace?.trace_id || null,
      request_id: payload.trace?.request_id || null,
      workflow: 'DALIA_M5_04_Invoicing',
      stage: 'invoicing_processed',
      processed_at: new Date().toISOString()
    }
  }
}];

const results = $input.all();
const output = results[results.length - 1].json;

return [{
  json: {
    result: output.result || { success: false, outcome: 'transaction_failed' },
    transaction: output.transaction || {},
    route: output.route || {},
    response: output.response || {},
    data: output.data || {},
    error: output.error || null,
    trace: output.trace || {}
  }
}];
